options.customCss:
  :root {
    --font-family: 'Open Sans', sans-serif;
    --font-family-header: 'Cormorant Garamond', serif;
    --font-weight-normal: 400;
    --font-weight-bold: 600;
    --font-size-body: 12px;
    --font-size-label: 14px;
    --font-size-input: 14px;
    --font-size-header: 30px;
    --font-size-subheader: 13px;
    --font-size-error: 12px;

    /* Colors — dark alumni theme */
    --color-background: #0e0e0f;
    --color-card-bg: #17171a;
    --color-card-border: #2b2b2f;
    --color-card-shadow: rgba(0, 0, 0, 0.45);
    --color-header: #f3f1ee;
    --color-header-subtext: #8f8c88;
    --color-label: #cfccc7;
    --color-input-bg: #1d1d20;
    --color-input-border: #35343a;
    --color-input-text: #ece9e5;
    --color-input-placeholder: #6c6a68;
    --color-focus-border: #9c2b3c;
    --color-focus-shadow: rgba(156, 43, 60, 0.28);
    --color-submit-btn-bg: #9c2b3c;
    --color-submit-btn-bg-hover: #b5334a;
    --color-submit-btn-text: #ffffff;
    --color-error: #e6566a;
    --color-required: #9c2b3c;
    --color-divider: #2b2b2f;

    /* Radii */
    --border-radius-card: 0px;
    --border-radius-input: 5px;
    --border-radius-checkbox: 3px;

    /* Spacing */
    --padding-card: 56px;
    --gap-row: 22px;
    --gap-field: 8px;

    /* Dimensions */
    --submit-btn-height: 48px;
    --checkbox-size: 16px;
  }

  *{ box-sizing: border-box; }

  body{
    margin:0;
    font-family: var(--font-family);
    background: var(--color-background);
    color: var(--color-input-text);
  }

  .wrap{
    min-height:100vh;
    display:flex;
  }

  /* ---- FORM PANEL ---- */
  .form-panel{
    flex: 0 0 58%;
    display:flex;
    align-items:center;
    justify-content:center;
    padding: 48px 40px;
    background: var(--color-background);
  }

  .card{
    width:100%;
    max-width: 560px;
  }

  .card h1{
    font-family: var(--font-family-header);
    font-weight:600;
    font-size: var(--font-size-header);
    letter-spacing: 0.08em;
    color: var(--color-header);
    text-align:center;
    margin: 0 0 20px;
    text-transform:uppercase;
  }

  .rule{
    height:1px;
    background: var(--color-divider);
    margin: 0 0 34px;
  }

  form{
    display:flex;
    flex-direction:column;
    gap: var(--gap-row);
  }

  .row{
    display:grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }

  .field{
    display:flex;
    flex-direction:column;
    gap: var(--gap-field);
  }

  label{
    font-size: var(--font-size-label);
    color: var(--color-label);
    font-weight: var(--font-weight-normal);
  }

  label .req{
    color: var(--color-required);
    margin-left:2px;
  }

  .input-wrap{
    position:relative;
  }

  input[type="text"],
  input[type="email"],
  input[type="tel"],
  input[type="number"],
  textarea{
    width:100%;
    font-family: var(--font-family);
    font-size: var(--font-size-input);
    color: var(--color-input-text);
    background: var(--color-input-bg);
    border: 1px solid var(--color-input-border);
    border-radius: var(--border-radius-input);
    padding: 12px 14px;
    outline:none;
    transition: border-color .15s ease, box-shadow .15s ease;
  }

  .input-wrap.has-icon input{
    padding-left: 42px;
  }

  .input-wrap .icon{
    position:absolute;
    left:14px;
    top:50%;
    transform:translateY(-50%);
    color: var(--color-input-placeholder);
    display:flex;
    align-items:center;
    pointer-events:none;
  }

  .input-wrap .flag{
    position:absolute;
    left:12px;
    top:50%;
    transform:translateY(-50%);
    font-size:16px;
    line-height:1;
  }

  .input-wrap.has-flag input{
    padding-left: 42px;
  }

  input::placeholder, textarea::placeholder{
    color: var(--color-input-placeholder);
  }

  input:focus, textarea:focus{
    border-color: var(--color-focus-border);
    box-shadow: 0 0 0 3px var(--color-focus-shadow);
  }

  textarea{
    min-height: 90px;
    resize: vertical;
  }

  .question-label{
    font-size: var(--font-size-label);
    color: var(--color-label);
    margin-bottom: 4px;
  }

  .check-row{
    display:flex;
    gap: 32px;
    flex-wrap:wrap;
  }

  .check-grid{
    display:grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px 32px;
  }

  .check-opt{
    display:flex;
    align-items:center;
    gap: 10px;
    font-size: var(--font-size-label);
    color: var(--color-input-text);
    cursor:pointer;
  }

  .check-opt input[type="checkbox"]{
    appearance:none;
    -webkit-appearance:none;
    width: var(--checkbox-size);
    height: var(--checkbox-size);
    border: 1px solid var(--color-input-border);
    border-radius: var(--border-radius-checkbox);
    background: var(--color-input-bg);
    cursor:pointer;
    position:relative;
    flex-shrink:0;
    transition: border-color .15s ease, background .15s ease;
  }

  .check-opt input[type="checkbox"]:checked{
    background: var(--color-focus-border);
    border-color: var(--color-focus-border);
  }

  .check-opt input[type="checkbox"]:checked::after{
    content:"";
    position:absolute;
    left:4px;
    top:1px;
    width:4px;
    height:8px;
    border:solid #fff;
    border-width: 0 2px 2px 0;
    transform: rotate(45deg);
  }

  .check-opt input[type="checkbox"]:focus-visible{
    outline: 2px solid var(--color-focus-border);
    outline-offset: 2px;
  }

  .donation-row{
    padding-top: 6px;
    border-top: 1px solid var(--color-divider);
  }

  .submit-btn{
    height: var(--submit-btn-height);
    background: var(--color-submit-btn-bg);
    color: var(--color-submit-btn-text);
    border:none;
    border-radius: var(--border-radius-input);
    font-size: 15px;
    font-weight: var(--font-weight-bold);
    letter-spacing: 0.03em;
    cursor:pointer;
    margin-top: 8px;
    transition: background .15s ease, transform .1s ease;
  }

  .submit-btn:hover{ background: var(--color-submit-btn-bg-hover); }
  .submit-btn:active{ transform: scale(0.99); }
  .submit-btn:focus-visible{
    outline: 2px solid var(--color-focus-border);
    outline-offset: 3px;
  }

  .err-msg{
    font-size: var(--font-size-error);
    color: var(--color-error);
    display:none;
  }
  .field.invalid input{ border-color: var(--color-error); }
  .field.invalid .err-msg{ display:block; }

  /* ---- VISUAL PANEL ---- */
  .visual-panel{
    flex: 0 0 42%;
    position:relative;
    background:
      radial-gradient(circle at 30% 20%, rgba(255,255,255,0.05), transparent 45%),
      linear-gradient(160deg, #2a2a2c 0%, #0a0a0b 70%);
    overflow:hidden;
    display:flex;
    align-items:center;
    justify-content:center;
  }

  .visual-panel::before{
    content:"";
    position:absolute;
    inset:0;
    background-image:
      repeating-linear-gradient(115deg, rgba(255,255,255,0.02) 0px, rgba(255,255,255,0.02) 1px, transparent 1px, transparent 60px);
  }

  .toast-photo{
    position:absolute;
    inset:0;
    width:100%;
    height:100%;
    object-fit:cover;
    z-index:0;
    filter: grayscale(15%) contrast(1.05);
  }
  .visual-overlay{
    position:absolute;
    inset:0;
    background: linear-gradient(180deg, rgba(10,10,11,0.15) 0%, rgba(10,10,11,0.55) 100%);
    z-index:1;
  }

    .toast-svg{
    position:relative;
    z-index:1;
    width: 62%;
    max-width: 320px;
    opacity: 0.92;
  }

  .visual-caption{
    position:absolute;
    bottom: 44px;
    left: 0; right:0;
    text-align:center;
    z-index:1;
    font-family: var(--font-family-header);
    font-size: 16px;
    letter-spacing: 0.12em;
    text-transform:uppercase;
    color: rgba(243,241,238,0.55);
  }

  @media (max-width: 920px){
    .wrap{ flex-direction:column; }
    .visual-panel{ flex:none; height: 220px; order:-1; }
    .form-panel{ flex:none; padding: 40px 22px; }
    .row{ grid-template-columns: 1fr; }
    .check-grid{ grid-template-columns: 1fr; }
    :root{ --padding-card: 0px; }
  }

  @media (prefers-reduced-motion: reduce){
    *{ transition:none !important; }
  }
</style>
</head>
<body>

<div class="wrap">
  <section class="form-panel">
    <div class="card">
      <h1>Alumni Event Registration</h1>
      <div class="rule"></div>

      <form id="alumniForm" novalidate>
        <div class="row">
          <div class="field" data-field="fullName">
            <label for="fullName">Full Name<span class="req">*</span></label>
            <div class="input-wrap">
              <input type="text" id="fullName" name="fullName" required>
            </div>
            <span class="err-msg">Full name is required.</span>
          </div>
          <div class="field" data-field="gradYear">
            <label for="gradYear">Graduation Year</label>
            <div class="input-wrap">
              <input type="text" id="gradYear" name="gradYear" placeholder="e.g. 2018">
            </div>
          </div>
        </div>

        <div class="row">
          <div class="field" data-field="email">
            <label for="email">Email<span class="req">*</span></label>
            <div class="input-wrap has-icon">
              <span class="icon">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 7l9 6 9-6"/></svg>
              </span>
              <input type="email" id="email" name="email" required>
            </div>
            <span class="err-msg">Enter a valid email address.</span>
          </div>
          <div class="field" data-field="contact">
            <label for="contact">Contact Number</label>
            <div class="input-wrap has-flag">
              <span class="flag">🇺🇸</span>
              <input type="tel" id="contact" name="contact" placeholder="(555) 000-0000">
            </div>
          </div>
        </div>

        <div class="row">
          <div class="field">
            <div class="question-label">Will you be attending the event?</div>
            <div class="check-row">
              <label class="check-opt"><input type="checkbox" name="attending" value="yes"> Yes</label>
              <label class="check-opt"><input type="checkbox" name="attending" value="no"> No</label>
            </div>
          </div>
          <div class="field">
            <label for="guests">Number of Guests</label>
            <div class="input-wrap">
              <input type="number" id="guests" name="guests" min="0" placeholder="0">
            </div>
          </div>
        </div>

        <div class="field">
          <div class="question-label">Which of the following activities would you like to participate in?</div>
          <div class="check-grid">
            <label class="check-opt"><input type="checkbox" name="activities" value="networking"> Networking Session</label>
            <label class="check-opt"><input type="checkbox" name="activities" value="panel"> Panel Discussion</label>
            <label class="check-opt"><input type="checkbox" name="activities" value="workshops"> Workshops</label>
            <label class="check-opt"><input type="checkbox" name="activities" value="awards"> Alumni Awards Ceremony</label>
          </div>
        </div>

        <div class="field">
          <label for="comments">Additional Comments or Special Requests:</label>
          <textarea id="comments" name="comments" placeholder="Let us know if there's anything we should be aware of..."></textarea>
        </div>

        <div class="field donation-row">
          <label class="check-opt"><input type="checkbox" name="donation" value="yes"> I would like to make a donation to support the event.</label>
        </div>

        <button type="submit" class="submit-btn">Register</button>
      </form>
    </div>
  </section>

  <aside class="visual-panel">
    <img class="toast-photo" src="data:image/jpeg;base64," alt="Celebration toast">
    <div class="visual-overlay"></div>
    <div class="visual-caption">You're Invited</div>
  </aside>
</div>

<script>
  const form = document.getElementById('alumniForm');

  function validateField(field){
    const input = field.querySelector('input[required]');
    if(!input) return true;
    const valid = input.checkValidity();
    field.classList.toggle('invalid', !valid);
    return valid;
  }

  form.querySelectorAll('.field[data-field]').forEach(f => {
    const input = f.querySelector('input');
    if(input){
      input.addEventListener('blur', () => validateField(f));
      input.addEventListener('input', () => {
        if(f.classList.contains('invalid')) validateField(f);
      });
    }
  });

  form.addEventListener('submit', function(e){
    e.preventDefault();
    let allValid = true;
    form.querySelectorAll('.field[data-field]').forEach(f => {
      if(!validateField(f)) allValid = false;
    });
    if(allValid){
      alert('Registration submitted. Thank you!');
      form.reset();
    } else {
      const firstInvalid = form.querySelector('.field.invalid input');
      if(firstInvalid) firstInvalid.focus();
    }
  });
</script>

</body>
</html>
